function renderDetail(){stopImageRefresh();
 if(widgetMode){
  stopOrbit();const s=resolveSystem(selected),valid=hasOrbitChart(s)&&systemFocused;
  document.body.classList.toggle('orbit-paused',orbitPaused);
  if(widgetRegion){
   $('mapArea').classList.remove('system-focused');
   $('systemFocus').innerHTML='';
   $('systemFocus').classList.add('hidden');
   $('detail').innerHTML='';
   $('map').setAttribute('aria-label',(DATA.regions[widgetRegion]?.name||'Dominion overview')+' regional chart. Select a system or world to open its article.');
   for(const node of document.querySelectorAll('[data-region], [data-region-shell]')){
    const region=node.dataset.region||node.dataset.regionShell;
    node.style.display=widgetRegion==='all'||region===widgetRegion?'':'none';
   }
   return;
  }
  $('mapArea').classList.add('system-focused');$('systemFocus').classList.remove('hidden');$('detail').innerHTML='';
  $('systemFocus').innerHTML=valid?`<div class="focus-visual">${cloakDecoration(s)}${silentDecoration(s)}<svg id="orbitDiagram" class="orbit-diagram" viewBox="0 0 760 580" tabindex="0" role="group" aria-label="${esc(planetFocus||s.name)} orbital widget. Focus this diagram and press Space to pause or play. Names and symbols open Codex articles."></svg></div>`:'<p class="widget-error" role="status">Choose a catalogued region, system, or planet for this widget.</p>';
  if(valid){mountSystem(s);const chart=$('orbitDiagram');chart.onkeydown=e=>{if(e.target===chart&&e.key===' '){e.preventDefault();toggleAtlasMotion('orbitDiagram')}}}
  return;
 }
 const focusScroll=$('systemFocus').scrollTop;stopOrbit();document.body.classList.toggle('orbit-paused',orbitPaused);
 const s=allRecords.find(x=>x.id===selected);selectedWorld=resolveObjectName(s,selectedWorld);syncSystemFocus(s);$('mobileInspect').textContent=s?(selectedWorld||s.name)+' dossier ↗':'Region dossier ↗';
 if(!s){const r=DATA.regions[view];$('detail').innerHTML=`<div class="detail-top"><span class="eyebrow">${r?'Regional dossier':'The Ordained Dominion'}</span><button class="detail-close" aria-label="Close dossier">×</button></div><div class="empty-detail"><div class="eyebrow">VERITAS ET ORDO</div><h2>${link(r?r.name:'Dominion of Calidor')}</h2><p>${r?esc(r.description):'Fifty-three systems along the rimward edge of the Cluster. The imperial capital at Calidor is sustained by the ancient Foundry; four black holes punctuate the Dominion’s charted territory.'}</p><div class="region-stat"><b>${r?DATA.systems.filter(s=>s.region===view).length:53}</b><span>charted systems</span></div><h3>The imperial heart</h3><p>Explore ${link('Calidor')}, ${link('Dominion City')} and the ${link('Foundry')}, an ancient Vy’Tiir stellar megastructure.</p><button class="focus-world" id="exploreCapital">Explore Calidor & the Foundry →</button><h3>Explore the atlas</h3><p>Double-click a system marker to enter its orbits, then double-click a planet to see every moon and local station. Names link to the Codex.</p><div class="note">Second edition. Original system positions follow your reference map; twenty new systems expand the register. Regional divisions, undocumented worlds, moons and facilities are creative additions. See Chart notes for source distinctions.</div>${link('Dominion of Calidor','Open national article ↗','region-link')}</div>`;bindDetail();$('exploreCapital').onclick=()=>{select('calidor');setSystemFocus(true)};return}

 const w=worldRecord(s,selectedWorld),display=w?selectedWorld:hasOrbitChart(s)?systemArticleTitle(s):s.name;
 const status=w?w.tag:s.centralBodyType==='silent-darkened'?'Dead system · Silent-darkened star':s.centralBodyType==='black-hole'?'Black hole system':EXOTIC_TYPES[s.centralBodyType]?EXOTIC_TYPES[s.centralBodyType]+' system':s.kind==='classified'?'Classified location':s.kind==='hazard'?'Hazard register':s.kind==='uncertain'?'Unresolved chart marker':s.kind==='context'?'Neighboring system':s.kind==='neutral'?'Independent / CONCORD':s.region?'Dominion region system':'Unplotted holding';
 $('detail').innerHTML=`<div class="detail-top"><span class="eyebrow">Location dossier</span><button class="detail-close" aria-label="Close dossier">×</button></div>${hasOrbitChart(s)?(systemFocused?'<div class="focused-dossier">System explorer is open in the main chart.<button id="returnSystem">← Return to '+(s.unplottedSystem?'chart':'region view')+'</button></div>':regionalSystemSummary(s)):`<div class="no-hero"><div class="orb"></div></div>${s.silentPresence?'<p class="silent-status" role="status">Silent activity detected · signal interference</p>':''}`}<div class="detail-content">${referenceImage(w||systemArticleRecord(s),display)}<div class="type" id="dossierType" data-atlas-type="${esc(status.toUpperCase())}">${esc(status.toUpperCase())}</div><h2>${link(display)}</h2>${(w||s).nickname?`<p class="nickname">${esc((w||s).nickname)}</p>`:''}<div class="system-subtitle">${s.region?`${systemLink(s)} / ${link(DATA.regions[s.region].name)}`:(s.unplottedSystem?systemLink(s)+' / ':'')+'POSITION '+(s.kind==='classified'?'CLASSIFIED':'UNSPECIFIED')}</div>${tierMarkup(s)}${cloakBadge(s)}<div id="bodyFacts">${bodyFacts(s,w,liveImages.get(currentImageTitle(w||systemArticleRecord(s),display)))}</div>${focusableWorld(s,selectedWorld)?`<button id="focusPlanet" class="focus-world">◎ &nbsp; ${planetFocus===selectedWorld?'Viewing local orbit':'Focus planet & satellites'}</button>`:''}${w?.name==='Foundry'&&!stationOverview?'<button class="focus-world" data-foundry-open="Foundry">Open Foundry schematic ↗</button>':''}<p class="description">${esc(w?w.description:s.description)}</p>${!systemFocused?notableSitesMarkup(s):''}${s.worlds.length&&!hasOrbitChart(s)?`<h3>Associated sites</h3>${s.worlds.map(n=>`<div class="world-chip ${selectedWorld===n?'active':''}">${link(n)}<button data-world="${esc(n)}" aria-label="View ${esc(n)} dossier">VIEW</button></div>`).join('')}`:''}${(w?.links||s.links||[]).length?`<h3>Related locations & records</h3><div class="link-pills">${(w?.links||s.links).map(n=>link(n)).join('')}</div>`:''}<a href="${url(display)}" target="_blank" rel="noopener" class="codex-button">Open ${esc(display)} in Codex ↗</a>${(s.notes||[]).map(n=>`<div class="note">${esc(n)}</div>`).join('')}<div class="source-line">${'Source: '+(w?.sourceNote?esc(w.sourceNote)+' · ':'')}${w?.sourceSection?`<a href="${esc(url(w.source)+'#'+encodeURIComponent(w.sourceSection))}" target="_blank" rel="noopener">${esc(w.source)} · station register</a>`:link(w?w.source:s.source)}${s.region&&s.source!==(w?.source)?'<br>Chart / context: '+link(s.source):''}<br>${s.unplottedSystem?'Coordinates withheld. Regional assignment unknown.':s.centralBodyType==='black-hole'||s.schematicPosition?'System position is schematic.':s.region&&DATA.regions[s.region]?.file?'System position follows the regional chart.':s.kind==='classified'?'Coordinates deliberately withheld.':s.region?'No measured coordinates available.':'No map coordinates assigned.'}</div></div>`;
 bindDetail();bindSystemControls();mountSystem(s);applySystemZoom();$('systemFocus').scrollTop=focusScroll;refreshVisibleImage();
}
